/** avian's settings: each one given is its resource, set at load (left out, the plugin's default). */
export function AvianSettings(props: {
  ColliderTreeDiagnostics?: ColliderTreeDiagnostics;
  CollisionDiagnostics?: CollisionDiagnostics;
  NarrowPhaseConfig?: NarrowPhaseConfig;
  Gravity?: Gravity;
  SolverDiagnostics?: SolverDiagnostics;
  ContactSoftnessCoefficients?: ContactSoftnessCoefficients;
  PhysicsLengthUnit?: PhysicsLengthUnit;
  SolverConfig?: SolverConfig;
  SubstepCount?: SubstepCount;
  PhysicsTransformConfig?: PhysicsTransformConfig;
  LastPhysicsTick?: LastPhysicsTick;
  SpatialQueryDiagnostics?: SpatialQueryDiagnostics;
}) {
  return (
    <>
      {props.ColliderTreeDiagnostics !== undefined && <BevyResource type="avian3d::collider_tree::diagnostics::ColliderTreeDiagnostics" value={props.ColliderTreeDiagnostics} />}
      {props.CollisionDiagnostics !== undefined && <BevyResource type="avian3d::collision::diagnostics::CollisionDiagnostics" value={props.CollisionDiagnostics} />}
      {props.NarrowPhaseConfig !== undefined && <BevyResource type="avian3d::collision::narrow_phase::NarrowPhaseConfig" value={props.NarrowPhaseConfig} />}
      {props.Gravity !== undefined && <BevyResource type="avian3d::dynamics::integrator::Gravity" value={props.Gravity} />}
      {props.SolverDiagnostics !== undefined && <BevyResource type="avian3d::dynamics::solver::diagnostics::SolverDiagnostics" value={props.SolverDiagnostics} />}
      {props.ContactSoftnessCoefficients !== undefined && <BevyResource type="avian3d::dynamics::solver::plugin::ContactSoftnessCoefficients" value={props.ContactSoftnessCoefficients} />}
      {props.PhysicsLengthUnit !== undefined && <BevyResource type="avian3d::dynamics::solver::plugin::PhysicsLengthUnit" value={props.PhysicsLengthUnit} />}
      {props.SolverConfig !== undefined && <BevyResource type="avian3d::dynamics::solver::plugin::SolverConfig" value={props.SolverConfig} />}
      {props.SubstepCount !== undefined && <BevyResource type="avian3d::dynamics::solver::schedule::SubstepCount" value={props.SubstepCount} />}
      {props.PhysicsTransformConfig !== undefined && <BevyResource type="avian3d::physics_transform::PhysicsTransformConfig" value={props.PhysicsTransformConfig} />}
      {props.LastPhysicsTick !== undefined && <BevyResource type="avian3d::schedule::LastPhysicsTick" value={props.LastPhysicsTick} />}
      {props.SpatialQueryDiagnostics !== undefined && <BevyResource type="avian3d::spatial_query::diagnostics::SpatialQueryDiagnostics" value={props.SpatialQueryDiagnostics} />}
    </>
  );
}

